// src/lib/plattform/akquise.js
//
// Akquise-Pipeline für Flächen: Scoring (Flächencheck aus src/lib/rechner/flaechencheck.js),
// Priorisierung, Gebietszuordnung (PLZ-Bereiche / Bundesland / Land → Mitarbeiter) und
// SLA-Ampel „Erstkontakt innerhalb von 2 Werktagen“. Reine Funktionen (Client + Server).

import { flaechencheck, BESONDERHEITEN, NETZ } from "../rechner/flaechencheck.js";
import { FREIFLAECHE } from "../invest/markt.js";

export { BESONDERHEITEN as AKQUISE_BESONDERHEITEN, NETZ as AKQUISE_NETZ };

export const SLA = { erstkontaktWerktage: 2 };

const REGION_DE = {
  "de-nord": ["Schleswig-Holstein", "Hamburg", "Niedersachsen", "Bremen", "Mecklenburg-Vorpommern"],
  "de-ost": ["Brandenburg", "Berlin", "Sachsen", "Sachsen-Anhalt", "Thüringen"],
  "de-west": ["Nordrhein-Westfalen", "Hessen", "Rheinland-Pfalz", "Saarland"],
  "de-sued": ["Bayern", "Baden-Württemberg"],
};
// Grobe Zuordnung der ersten PLZ-Ziffer (DE), falls kein Bundesland angegeben ist
const PLZ_REGION_DE = { 0: "de-ost", 1: "de-ost", 2: "de-nord", 3: "de-nord", 4: "de-west", 5: "de-west", 6: "de-west", 7: "de-sued", 8: "de-sued", 9: "de-sued" };

export function regionFuer({ land, bundesland, plz }) {
  if (land === "AT") return "at";
  if (land === "CH") return "ch";
  for (const [id, laender] of Object.entries(REGION_DE)) if (laender.includes(bundesland)) return id;
  const z = String(plz || "").trim()[0];
  return PLZ_REGION_DE[z] || "de-sued";
}

const NUTZUNG = { acker: "acker", gruenland: "gruenland", konversion: "konversion", gewerbe: "parkplatz", sonstige: "sonstige" };
const EIGENTUM = { eigentum: "allein", miteigentum: "gemeinschaft", verwaltung: "gemeinschaft" };

/** Flächencheck für eine Plattform-Fläche (+ Akquise-Zusatzangaben: besonderheiten, netz) */
export function flaechenScore(f, zusatz = {}) {
  const ha = Number(f?.ha) || 0;
  const r = flaechencheck({
    land: f?.land || "DE",
    regionId: regionFuer(f || {}),
    ha: ha > 0 ? ha : 0.5,
    nutzung: NUTZUNG[f?.nutzung] || "sonstige",
    besonderheiten: (zusatz.besonderheiten || []).filter((b) => BESONDERHEITEN.some((x) => x.id === b)),
    netz: NETZ.some((n) => n.id === zusatz.netz) ? zusatz.netz : "unbekannt",
    eigentum: EIGENTUM[f?.eigentum] || "allein",
  });
  return {
    score: ha > 0 ? r.score : Math.min(r.score, 30),
    ampel: ha > 0 ? r.ampel : "rot",
    mwp: ha > 0 ? Math.round((ha / FREIFLAECHE.haProMwp) * 10) / 10 : 0,
    gruende: r.gruende.slice(0, 4).map((g) => ({ text: g.text, art: g.art, punkte: g.punkte })),
  };
}

/** Automatische Priorität aus Score und Größe (manuell überschreibbar) */
export function prioritaetAuto(score, ha) {
  if (score >= 65 && (Number(ha) || 0) >= 5) return "A";
  if (score >= 45) return "B";
  return "C";
}

// ------------------------------------------------------------ Werktage & SLA

const istWerktag = (d) => d.getUTCDay() !== 0 && d.getUTCDay() !== 6;

/** Zeitpunkt `werktage` Werktage (Mo–Fr) nach `iso`; Eingang am Wochenende zählt ab Montag */
export function werktageSpaeter(iso, werktage = SLA.erstkontaktWerktage) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  while (!istWerktag(d)) {
    d.setUTCDate(d.getUTCDate() + 1);
    d.setUTCHours(7, 0, 0, 0);
  }
  let rest = werktage;
  while (rest > 0) {
    d.setUTCDate(d.getUTCDate() + 1);
    if (istWerktag(d)) rest--;
  }
  return d.toISOString();
}

/**
 * SLA-Ampel Erstkontakt. `eingangAm` = Eingang (Anfrage bzw. Einreichung), `erstkontaktAm` = erster
 * Kontakt durch das Backoffice (Anruf/E-Mail/Termin im CRM, Nachricht im Thread oder Statuswechsel).
 * Liefert { ampel: gruen|gelb|rot, status: erledigt|verspaetet|offen|faellig|ueberfaellig, fristBis, text }.
 */
export function slaStatus(eingangAm, erstkontaktAm, jetzt = Date.now()) {
  if (!eingangAm) return { ampel: "grau", status: "unbekannt", fristBis: null, text: "Kein Eingang" };
  const frist = werktageSpaeter(eingangAm);
  const fristMs = new Date(frist).getTime();
  const stunden = (a, b) => Math.max(0, Math.round((b - a) / 36e5));
  if (erstkontaktAm) {
    const k = new Date(erstkontaktAm).getTime();
    if (k <= fristMs) return { ampel: "gruen", status: "erledigt", fristBis: frist, erstkontaktAm, text: `Erstkontakt nach ${stunden(new Date(eingangAm).getTime(), k)} h` };
    return { ampel: "gelb", status: "verspaetet", fristBis: frist, erstkontaktAm, text: `Erstkontakt verspätet (${stunden(fristMs, k)} h nach Frist)` };
  }
  if (jetzt > fristMs) return { ampel: "rot", status: "ueberfaellig", fristBis: frist, text: `Erstkontakt überfällig seit ${stunden(fristMs, jetzt)} h` };
  if (fristMs - jetzt < 24 * 36e5) return { ampel: "gelb", status: "faellig", fristBis: frist, text: `Erstkontakt fällig in ${stunden(jetzt, fristMs)} h` };
  return { ampel: "gruen", status: "offen", fristBis: frist, text: `Frist läuft (${stunden(jetzt, fristMs)} h)` };
}

// ------------------------------------------------------------ Gebiete

/** PLZ passt zu einem Eintrag wie "80-87", "9", "5020" (Präfix bzw. Präfix-Bereich) */
export function plzPasst(plz, muster) {
  const p = String(plz || "").replace(/\D/g, "");
  const m = String(muster || "").replace(/\s/g, "");
  if (!p || !m) return false;
  const bereich = m.match(/^(\d{1,5})-(\d{1,5})$/);
  if (bereich) {
    const [von, bis] = [bereich[1], bereich[2]];
    const len = Math.max(von.length, bis.length);
    const kopf = Number(p.slice(0, len));
    return p.length >= len && kopf >= Number(von.padEnd(len, "0")) && kopf <= Number(bis.padEnd(len, "9"));
  }
  return /^\d{1,5}$/.test(m) && p.startsWith(m);
}

/** Bestes Gebiet für ein Objekt: PLZ (3) vor Bundesland (2) vor Land (1). Liefert { gebiet, grund } oder null */
export function gebietFuer(gebiete = [], { land, bundesland, plz }) {
  let best = null;
  for (const g of gebiete) {
    if (g.aktiv === false || !g.mitarbeiterId) continue;
    if (g.land && land && g.land !== land) continue;
    let punkte = 0;
    let grund = "";
    if ((g.plz || []).some((m) => plzPasst(plz, m))) {
      punkte = 3;
      grund = `PLZ ${plz}`;
    } else if ((g.bundeslaender || []).includes(bundesland)) {
      punkte = 2;
      grund = bundesland;
    } else if (g.land && g.land === land && !(g.plz || []).length && !(g.bundeslaender || []).length) {
      punkte = 1;
      grund = `Land ${land}`;
    }
    if (punkte && (!best || punkte > best.punkte)) best = { gebiet: g, punkte, grund };
  }
  return best;
}
// src/lib/plattform/backend/demo/akquise.js
//
// Akquise-Pipeline Flächen im Demo-Backend: Scoring (Flächencheck), Priorität (automatisch,
// manuell überschreibbar), Zuständigkeit und Gebietszuordnung (PLZ-Bereiche/Bundesland/Land →
// Mitarbeiter), SLA-Ampel Erstkontakt < 2 Werktage, Massen-Zuweisung.

import * as v from "../../validierung";
import { nichtGefunden } from "../../fehler";
import { BUNDESLAENDER, LAENDER } from "../../konstanten";
import { statusLabel } from "../../prozesse";
import { AKQUISE_BESONDERHEITEN, AKQUISE_NETZ, flaechenScore, gebietFuer, prioritaetAuto, slaStatus } from "../../akquise";
import { jetzt, neueId } from "./hilfen";
import { W, boAendern, boLesen, eingangAm, erstkontaktAm, info, kontaktVon, kurzKonto, nameVon, nutzerVon, objektVon, rechtNoetig, tagsVon } from "./bo-kern";
import { fristenBeiBedarf } from "./automation";

const OFFEN = ["entwurf", "eingegangen", "vorpruefung", "standortanalyse", "pachtangebot", "vertrag", "planung"];

function zeile(db, f) {
  const i = info(db, "flaeche", f.id);
  const s = flaechenScore(f, i);
  const auto = prioritaetAuto(s.score, f.ha);
  const ein = eingangAm(db, "flaeche", f);
  const sla = f.status === "entwurf" && !f.vorgangId ? { ampel: "grau", status: "entwurf", text: "Noch nicht eingereicht" } : slaStatus(ein, erstkontaktAm(db, "flaeche", f, ein));
  const g = gebietFuer(db.bo.gebiete, { land: f.land, bundesland: f.bundesland, plz: f.plz });
  const k = kontaktVon(db, "flaeche", f);
  const eigentuemer = nutzerVon(db, f.nutzerId);
  return {
    id: f.id,
    bezeichnung: f.bezeichnung,
    land: f.land,
    bundesland: f.bundesland,
    plz: f.plz,
    ort: f.ort,
    ha: f.ha,
    nutzung: f.nutzung,
    agri: !!f.agri,
    status: f.status,
    statusLabel: statusLabel("flaeche", f.status),
    vorgangId: f.vorgangId || null,
    score: s.score,
    ampel: s.ampel,
    mwp: s.mwp,
    gruende: s.gruende,
    prioritaet: i.prioritaet || auto,
    prioritaetManuell: !!i.prioritaet,
    prioritaetAuto: auto,
    besonderheiten: i.besonderheiten || [],
    netz: i.netz || "unbekannt",
    tags: tagsVon(db, "flaeche", f.id),
    zustaendig: kurzKonto(nutzerVon(db, f.zustaendigId)),
    gebiet: g ? { id: g.gebiet.id, name: g.gebiet.name, grund: g.grund, mitarbeiter: kurzKonto(nutzerVon(db, g.gebiet.mitarbeiterId)) } : null,
    sla,
    eingangAm: ein,
    kontakt: k ? { id: k.id || null, name: [k.vorname, k.nachname].filter(Boolean).join(" ") || k.email, email: k.email || eigentuemer?.email || "" } : null,
    geaendertAm: f.geaendertAm,
  };
}

const PRIO_RANG = { A: 0, B: 1, C: 2 };
const SLA_RANG = { rot: 0, gelb: 1, gruen: 2, grau: 3 };

export async function akquise(n, { land, prioritaet, sla, zustaendigId, status, q, alle = false } = {}) {
  rechtNoetig(n, "akquise", 1);
  await fristenBeiBedarf();
  const db = await boLesen();
  let liste = db.flaechen.filter((f) => alle || OFFEN.includes(f.status)).map((f) => zeile(db, f));
  const alleZeilen = liste;
  if (land) liste = liste.filter((z) => z.land === land);
  if (prioritaet) liste = liste.filter((z) => z.prioritaet === prioritaet);
  if (sla) liste = liste.filter((z) => z.sla.ampel === sla);
  if (zustaendigId === "ohne") liste = liste.filter((z) => !z.zustaendig);
  else if (zustaendigId) liste = liste.filter((z) => z.zustaendig?.id === zustaendigId);
  if (status) liste = liste.filter((z) => z.status === status);
  if (q) {
    const s = String(q).toLowerCase();
    liste = liste.filter((z) => [z.id, z.bezeichnung, z.ort, z.plz, z.bundesland, z.kontakt?.name, z.kontakt?.email, z.tags.join(" ")].join(" ").toLowerCase().includes(s));
  }
  liste.sort((a, b) => PRIO_RANG[a.prioritaet] - PRIO_RANG[b.prioritaet] || SLA_RANG[a.sla.ampel] - SLA_RANG[b.sla.ampel] || b.score - a.score);
  const summe = (l, f) => Math.round(l.reduce((s, z) => s + (Number(z[f]) || 0), 0) * 10) / 10;
  return {
    flaechen: liste,
    kennzahlen: {
      anzahl: alleZeilen.length,
      ha: summe(alleZeilen, "ha"),
      mwp: summe(alleZeilen, "mwp"),
      slaRot: alleZeilen.filter((z) => z.sla.ampel === "rot").length,
      slaGelb: alleZeilen.filter((z) => z.sla.ampel === "gelb").length,
      ohneZustaendig: alleZeilen.filter((z) => !z.zustaendig).length,
      prioA: alleZeilen.filter((z) => z.prioritaet === "A").length,
      scoreMittel: alleZeilen.length ? Math.round(alleZeilen.reduce((s, z) => s + z.score, 0) / alleZeilen.length) : 0,
    },
    konten: db.nutzer.filter((u) => u.aktiv && u.rollen.includes("admin")).map(kurzKonto),
    gebiete: db.bo.gebiete.map((g) => ({ ...g, mitarbeiter: kurzKonto(nutzerVon(db, g.mitarbeiterId)) })),
  };
}

export async function akquiseSetzen(n, flaecheId, daten = {}) {
  rechtNoetig(n, "akquise", 2);
  return boAendern((db) => {
    const f = objektVon(db, "flaeche", v.kennung(flaecheId));
    if (!f) throw nichtGefunden("Fläche nicht gefunden.");
    const i = info(db, "flaeche", f.id, true);
    const teile = [];
    if (daten.prioritaet !== undefined) {
      i.prioritaet = ["A", "B", "C"].includes(daten.prioritaet) ? daten.prioritaet : null;
      teile.push(`Priorität ${i.prioritaet || "automatisch"}`);
    }
    if (daten.besonderheiten !== undefined) {
      i.besonderheiten = v.mehrfach(daten.besonderheiten, AKQUISE_BESONDERHEITEN.map((b) => b.id));
      teile.push("Besonderheiten");
    }
    if (daten.netz !== undefined) {
      i.netz = v.auswahl(daten.netz, AKQUISE_NETZ.map((x) => x.id), "unbekannt");
      teile.push("Netzentfernung");
    }
    W.protokoll(db, n, "akquise", "flaeche", f.id, `Akquise: ${teile.join(", ") || "gespeichert"}`);
    return zeile(db, f);
  });
}

export async function gebiete(n) {
  rechtNoetig(n, "akquise", 1);
  const db = await boLesen();
  return { gebiete: db.bo.gebiete.map((g) => ({ ...g, mitarbeiter: kurzKonto(nutzerVon(db, g.mitarbeiterId)) })), konten: db.nutzer.filter((u) => u.aktiv && u.rollen.includes("admin")).map(kurzKonto) };
}

/** Gebiete vollständig ersetzen (Liste aus dem Editor) */
export async function gebieteSpeichern(n, liste = []) {
  rechtNoetig(n, "akquise", 2);
  v.pflicht(Array.isArray(liste) && liste.length <= 100, "Höchstens 100 Gebiete.");
  return boAendern((db) => {
    const neu = liste.map((g) => {
      const land = v.auswahl(g.land, LAENDER, "");
      const name = v.text(g.name, 80);
      v.pflicht(name.length >= 2, "Jedes Gebiet braucht einen Namen.");
      const mitarbeiterId = v.kennung(g.mitarbeiterId);
      const u = nutzerVon(db, mitarbeiterId);
      v.pflicht(u && u.aktiv && u.rollen.includes("admin"), `Gebiet „${name}“: Zuständig kann nur ein aktives Backoffice-Konto sein.`);
      const plz = (Array.isArray(g.plz) ? g.plz : String(g.plz || "").split(","))
        .map((x) => String(x).replace(/\s/g, ""))
        .filter(Boolean)
        .slice(0, 30);
      v.pflicht(plz.every((x) => /^\d{1,5}(-\d{1,5})?$/.test(x)), `Gebiet „${name}“: PLZ-Bereiche wie „80-87“ oder „9“ angeben.`);
      const bl = v.mehrfach(g.bundeslaender, land ? BUNDESLAENDER[land] || [] : Object.values(BUNDESLAENDER).flat());
      v.pflicht(land || plz.length || bl.length, `Gebiet „${name}“: Land, Bundesland oder PLZ-Bereich angeben.`);
      return { id: v.kennung(g.id) || neueId("GE"), name, land, bundeslaender: bl, plz, mitarbeiterId, aktiv: g.aktiv !== false };
    });
    db.bo.gebiete = neu;
    W.protokoll(db, n, "akquise", "gebiete", "gebiete", `Gebietszuordnung gespeichert (${neu.length} Gebiete)`);
    return { gebiete: neu.map((g) => ({ ...g, mitarbeiter: kurzKonto(nutzerVon(db, g.mitarbeiterId)) })), gespeichertAm: jetzt() };
  });
}

/** Massen-Zuweisung: nach Gebiet oder an eine Person. Vorgang zur Fläche erhält dieselbe Person, wenn frei. */
export async function akquiseZuweisen(n, { ids = [], modus = "gebiet", zustaendigId, ueberschreiben = false } = {}) {
  rechtNoetig(n, "akquise", 2);
  rechtNoetig(n, "flaechen", 2);
  return boAendern((db) => {
    const liste = (Array.isArray(ids) ? ids : []).map(v.kennung).filter(Boolean).slice(0, 500);
    v.pflicht(liste.length, "Bitte Flächen auswählen.");
    if (modus !== "gebiet") {
      const u = nutzerVon(db, zustaendigId);
      v.pflicht(u && u.aktiv && u.rollen.includes("admin"), "Zuständig kann nur ein aktives Backoffice-Konto sein.");
    }
    const ergebnis = { zugewiesen: 0, uebersprungen: 0, ohneGebiet: 0 };
    for (const id of liste) {
      const f = objektVon(db, "flaeche", id);
      if (!f) continue;
      if (f.zustaendigId && !ueberschreiben) {
        ergebnis.uebersprungen++;
        continue;
      }
      let ziel = zustaendigId;
      let grund = "manuell";
      if (modus === "gebiet") {
        const g = gebietFuer(db.bo.gebiete, { land: f.land, bundesland: f.bundesland, plz: f.plz });
        if (!g) {
          ergebnis.ohneGebiet++;
          continue;
        }
        ziel = g.gebiet.mitarbeiterId;
        grund = `Gebiet „${g.gebiet.name}“`;
      }
      f.zustaendigId = ziel;
      f.geaendertAm = jetzt();
      const vg = f.vorgangId ? objektVon(db, "vorgang", f.vorgangId) : null;
      if (vg && (!vg.zustaendigId || ueberschreiben)) vg.zustaendigId = ziel;
      W.protokoll(db, n, "zuweisen", "flaeche", f.id, `Zuständig: ${nameVon(db, ziel)} (${grund})`);
      ergebnis.zugewiesen++;
    }
    return ergebnis;
  });
}
import Link from "next/link";
import { AlarmClock, Gauge, LandPlot, MapPinned, Search, Star, UserX } from "lucide-react";
import { Karte, Kennzahl, SeitenKopf } from "@/components/Portal/ui";
import { auswahlfeld, eingabe } from "@/components/Portal/felder";
import { cn } from "@/components/ui/cn";
import { AkquiseTabelle, GebieteEditor } from "@/components/Portal/Backoffice/Akquise";
import { portalNutzer } from "@/lib/plattform/server/seite";
import { backend } from "@/lib/plattform/backend";
import { LAENDER } from "@/lib/plattform/konstanten";
import { PROZESSE } from "@/lib/plattform/prozesse";
import { darfSchreiben } from "@/lib/plattform/rechte";
import { fmt } from "@/lib/rechner/annahmen";

export const metadata = { title: "Akquise & Gebiete" };

export default async function AdminAkquise({ searchParams }) {
  const n = await portalNutzer({ admin: true });
  const sp = await searchParams;
  const filter = {
    land: LAENDER[sp?.land] ? sp.land : "",
    prioritaet: ["A", "B", "C"].includes(sp?.prioritaet) ? sp.prioritaet : "",
    sla: ["gruen", "gelb", "rot"].includes(sp?.sla) ? sp.sla : "",
    zustaendigId: typeof sp?.zustaendig === "string" ? sp.zustaendig.slice(0, 40) : "",
    status: PROZESSE.flaeche.status[sp?.status] ? sp.status : "",
    q: typeof sp?.q === "string" ? sp.q.slice(0, 80) : "",
  };
  const r = await backend().akquise(n, Object.fromEntries(Object.entries(filter).filter(([, x]) => x)));
  const k = r.kennzahlen;
  const schreiben = darfSchreiben(n, "akquise");
  const link = (extra) => `/portal/admin/akquise?${new URLSearchParams({ ...Object.fromEntries(Object.entries(filter).filter(([, x]) => x)), ...extra })}`;

  return (
    <div className="space-y-6">
      <SeitenKopf eyebrow="Backoffice" titel="Akquise-Pipeline Flächen" text="Score aus dem Flächencheck, Priorität, Zuständigkeit nach Gebiet und SLA-Ampel für den Erstkontakt (innerhalb von 2 Werktagen)." />

      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <Kennzahl label="Offene Flächen" wert={fmt(k.anzahl)} hinweis={`${fmt(k.ha)} ha · ≈ ${fmt(k.mwp)} MWp Potenzial`} icon={LandPlot} />
        <Kennzahl label="Priorität A" wert={fmt(k.prioA)} hinweis={`Score im Mittel ${k.scoreMittel}`} icon={Star} href={link({ prioritaet: "A" })} />
        <Kennzahl label="Erstkontakt überfällig" wert={fmt(k.slaRot)} hinweis={`${fmt(k.slaGelb)} knapp oder verspätet`} icon={AlarmClock} href={link({ sla: "rot" })} ton={k.slaRot ? "dunkel" : "hell"} />
        <Kennzahl label="Ohne Zuständigen" wert={fmt(k.ohneZustaendig)} hinweis="Auswählen → „Nach Gebiet zuweisen“" icon={UserX} href={link({ zustaendig: "ohne" })} />
      </div>

      <form method="get" className="grid gap-3 rounded-3xl bg-white p-4 ring-1 ring-ink-200/70 md:grid-cols-3 xl:grid-cols-[minmax(0,1.5fr)_repeat(5,minmax(0,1fr))_auto]">
        <label className="relative md:col-span-3 xl:col-span-1">
          <span className="sr-only">Suche</span>
          <Search aria-hidden="true" className="pointer-events-none absolute left-3.5 top-3.5 h-5 w-5 text-ink-400" />
          <input name="q" defaultValue={filter.q} placeholder="Fläche, Ort, PLZ, Kontakt, Tag" className={cn(eingabe, "pl-11")} />
        </label>
        <label>
          <span className="sr-only">Land</span>
          <select name="land" defaultValue={filter.land} className={auswahlfeld}>
            <option value="">Alle Länder</option>
            {Object.entries(LAENDER).map(([id, l]) => <option key={id} value={id}>{l}</option>)}
          </select>
        </label>
