  vorlagen: [2, 2, 2, 1, 1],
  automationen: [2, 1, 1, 0, 1],
  berichte: [2, 1, 1, 2, 1],
  export: [2, 1, 1, 1, 0],
  postausgang: [2, 1, 1, 0, 1],
  nutzer: [2, 1, 1, 1, 1],
