}

SUED = ("S", "SO", "SW", "eben")


def r1(x):
	return jsround(x * 10) / 10


def clamp(x, a=0.0, b=1.0):
	return max(a, min(b, x))


def mwp_fuer(ha):
	return r1((float(ha or 0)) / FREIFLAECHE["haProMwp"])


def trasse_m(luftlinie_m, querungen=0):
