    return { name: f.name, eingabe: m, erwartet: { score: r.score, ampel: r.ampel, ko: r.ko.map((k) => k.id), punkte: Object.fromEntries(r.kriterien.map((k) => [k.id, k.punkte])), mwp: r.mwp } };
