  return new Response(kandidatenCsv(r.kandidaten), {
    headers: { "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": `attachment; filename="kandidatenflaechen-${datum}.csv"`, "Cache-Control": "no-store" },
