                <li key={p.id} className="flex justify-between gap-2"><span>{p.kg} ({p.kgNr}) · Gst. {p.gstNr}</span><span className="ov-num shrink-0">{fmt(p.ha, 2)} ha · {p.nutzung}</span></li>
              ))}
